$1 != "" && $1 != "Value" { 
  a = strtonum("0x" $1)
  if (a <= t && $2 == "FUNC") { best_addr = $1; best_name = $3 }
  if (a > t && found == 0) { found = 1; print "Before:", best_addr, best_name; print "After:", $1, $3 }
}' 2>/dev/null
echo "---"
# Try with nm which sometimes gives better results
readelf -sW mono.debug | grep FUNC | awk '{printf "%s %s %s\n", $2, $3, $8}' | sort | awk '
