{
  addr = strtonum("0x" $1)
  size = strtonum($2)
  if (addr <= target1 && (addr + size > target1 || size == 0)) { best1_addr = $1; best1_name = $3; best1_size = size }
  if (addr <= target2 && (addr + size > target2 || size == 0)) { best2_addr = $1; best2_name = $3; best2_size = size }
}
END { 
  print "0x2f4b20 nearest FUNC:", best1_addr, best1_name, "size:", best1_size
  print "0x2f4c84 nearest FUNC:", best2_addr, best2_name, "size:", best2_size
}'

